<?php
namespace App\Filament\Resources\DiscordChannelResource\Pages; use App\Filament\Resources\DiscordChannelResource; use App\Models\DiscordGuild; use App\Services\DiscordGuildSyncService; use Filament\Actions; use Filament\Notifications\Notification; use Filament\Resources\Pages\ListRecords; use Throwable;
class ListDiscordChannels extends ListRecords {protected static string $resource=DiscordChannelResource::class; protected function getHeaderActions():array{return [Actions\Action::make('refreshVoiceChannels')->label('Réactualiser les salons vocaux')->icon('heroicon-o-arrow-path')->color('gray')->action(function(): void {$synced=0;$failed=[];DiscordGuild::query()->whereNotNull('discord_bot_id')->get()->each(function(DiscordGuild $guild) use (&$synced,&$failed): void {try{app(DiscordGuildSyncService::class)->sync($guild);$synced++;}catch(Throwable $error){$failed[]=$guild->name.': '.$error->getMessage();}});if($failed!==[]){Notification::make()->title('Synchronisation partielle')->body($synced.' serveur(s) synchronisé(s). '.count($failed).' erreur(s). '.$failed[0])->warning()->send();return;}Notification::make()->title('Salons vocaux réactualisés')->body($synced.' serveur(s) synchronisé(s).')->success()->send();}),Actions\CreateAction::make()];}}
